#!/usr/bin/env python3
import curses
import locale
import os
import re
import subprocess
import sys
import textwrap
import time
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

VERSION = "keifu 0.2.3"
DESC = "A TUI tool to visualize Git commit graphs with branch genealogy"


def progname():
    return os.path.basename(sys.argv[0]) or "executable"


def print_help():
    p = progname()
    sys.stdout.write(f"{DESC}\n\nUsage: {p}\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version\n")


def cli_error(msg, usage_suffix=""):
    p = progname()
    sys.stderr.write(f"error: {msg}\n\nUsage: {p}{usage_suffix}\n\nFor more information, try '--help'.\n")
    raise SystemExit(2)


def parse_args(argv):
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            # No positional arguments are accepted; clap allows a bare terminator.
            if i + 1 < len(argv):
                cli_error(f"unexpected argument '{argv[i+1]}' found")
            return
        if a == "--help":
            print_help(); raise SystemExit(0)
        if a == "--version":
            sys.stdout.write(VERSION + "\n"); raise SystemExit(0)
        if a.startswith("--help="):
            val = a.split("=", 1)[1]
            cli_error(f"unexpected value '{val}' for '--help' found; no more were expected", " --help")
        if a.startswith("--version="):
            val = a.split("=", 1)[1]
            cli_error(f"unexpected value '{val}' for '--version' found; no more were expected", " --version")
        if a.startswith("-") and a != "-":
            if a.startswith("--"):
                opt = a.split("=", 1)[0]
                cli_error(f"unexpected argument '{opt}' found")
            # short option cluster, first recognized action wins
            for ch in a[1:]:
                if ch == 'h':
                    print_help(); raise SystemExit(0)
                if ch == 'V':
                    sys.stdout.write(VERSION + "\n"); raise SystemExit(0)
                cli_error(f"unexpected argument '{a}' found")
        else:
            cli_error(f"unexpected argument '{a}' found")
        i += 1


def run_git(args, cwd=None, check=False, input_data=None):
    p = subprocess.run(["git"] + args, cwd=cwd, input=input_data, text=True,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if check and p.returncode != 0:
        raise RuntimeError(p.stderr.strip() or p.stdout.strip() or f"git {' '.join(args)} failed")
    return p


def git_out(args, default=""):
    p = run_git(args)
    if p.returncode != 0:
        return default
    return p.stdout.rstrip("\n")


@dataclass
class RefInfo:
    name: str
    commit: str
    kind: str = "local"  # local or remote
    upstream: Optional[str] = None
    label: Optional[str] = None


@dataclass
class CommitInfo:
    graph: str
    hash: str
    author: str
    email: str
    date_full: str
    subject: str
    parents: List[str]
    labels: List[str] = field(default_factory=list)
    local_labels: List[str] = field(default_factory=list)
    selected_label_index: int = 0


@dataclass
class Row:
    kind: str  # commit or connector
    graph: str
    commit_index: Optional[int] = None


class GitModel:
    def __init__(self):
        self.repo_root = ""
        self.repo_name = ""
        self.current_branch = ""
        self.head_hash = ""
        self.current_branch_hash = ""
        self.commits: List[CommitInfo] = []
        self.rows: List[Row] = []
        self.commit_to_row: Dict[int, int] = {}
        self.refs_by_hash: Dict[str, List[RefInfo]] = {}
        self.all_branch_names: List[Tuple[str, str, str]] = []  # label, commit, kind
        self.graph_width = 1

    def discover(self) -> bool:
        p = run_git(["rev-parse", "--show-toplevel"])
        if p.returncode != 0:
            return False
        self.repo_root = p.stdout.strip()
        self.repo_name = os.path.basename(self.repo_root) or self.repo_root
        return True

    def refresh(self):
        root = git_out(["rev-parse", "--show-toplevel"], os.getcwd())
        if root:
            self.repo_root = root
            self.repo_name = os.path.basename(root) or root
        self.current_branch = git_out(["branch", "--show-current"])
        self.head_hash = git_out(["rev-parse", "HEAD"])
        self.current_branch_hash = ""
        if self.current_branch:
            self.current_branch_hash = git_out(["rev-parse", self.current_branch])
        self._load_refs()
        self._load_commits()

    def _load_refs(self):
        locals_: List[RefInfo] = []
        remotes: List[RefInfo] = []
        p = run_git(["for-each-ref", "--format=%(refname:short)%00%(objectname)", "refs/heads"])
        if p.returncode == 0:
            for line in p.stdout.splitlines():
                if "\x00" in line:
                    name, h = line.split("\x00", 1)
                    if name:
                        locals_.append(RefInfo(name=name, commit=h, kind="local"))
        p = run_git(["for-each-ref", "--format=%(refname:short)%00%(objectname)", "refs/remotes"])
        if p.returncode == 0:
            for line in p.stdout.splitlines():
                if "\x00" in line:
                    name, h = line.split("\x00", 1)
                    if name.endswith("/HEAD"):
                        continue
                    remotes.append(RefInfo(name=name, commit=h, kind="remote"))
        # Discover upstreams for local branches.  The original combines "master" + "origin/master"
        # as "master ↔ origin" when both point to the same commit.
        remote_consumed = set()
        for r in locals_:
            up = git_out(["rev-parse", "--abbrev-ref", f"{r.name}@{{upstream}}"], "")
            if up:
                r.upstream = up
                up_hash = git_out(["rev-parse", up], "")
                if up_hash and up_hash == r.commit:
                    remote_consumed.add(up)
                    if "/" in up:
                        remote, rest = up.split("/", 1)
                        if rest == r.name:
                            r.label = f"{r.name} ↔ {remote}"
                        else:
                            r.label = f"{r.name} ↔ {up}"
                    else:
                        r.label = f"{r.name} ↔ {up}"
            if not r.label:
                r.label = r.name
        for r in remotes:
            r.label = r.name
        refs = locals_ + [r for r in remotes if r.name not in remote_consumed]
        by: Dict[str, List[RefInfo]] = {}
        for r in refs:
            by.setdefault(r.commit, []).append(r)
        def sort_key(ref: RefInfo):
            cur_rank = 0 if (ref.kind == "local" and ref.name == self.current_branch) else 1
            kind_rank = 0 if ref.kind == "local" else 1
            return (cur_rank, kind_rank, ref.name)
        for h in by:
            by[h].sort(key=sort_key)
        self.refs_by_hash = by
        self.all_branch_names = []
        # Search shows local and remote refs, sorted in the same predictable order.
        for r in sorted(refs, key=lambda x: (0 if x.kind == "local" else 1, x.name)):
            self.all_branch_names.append((r.label or r.name, r.commit, r.kind))

    def _load_commits(self):
        self.commits = []
        self.rows = []
        self.commit_to_row = {}
        self.graph_width = 1
        p = run_git(["log", "--graph", "--all", "--date-order",
                     "--date=format:%Y-%m-%d %H:%M:%S",
                     "--pretty=format:%x1e%H%x1f%an%x1f%ae%x1f%ad%x1f%s%x1f%P"])
        if p.returncode != 0 or not p.stdout:
            return
        lines = p.stdout.splitlines()
        for line in lines:
            if "\x1e" in line:
                graph_prefix, rest = line.split("\x1e", 1)
                parts = rest.split("\x1f")
                while len(parts) < 6:
                    parts.append("")
                h, an, ae, ad, subj, parents_s = parts[:6]
                parents = [x for x in parents_s.split() if x]
                node_head = bool(self.current_branch_hash and h == self.current_branch_hash)
                ug = self._unicode_commit_graph(graph_prefix, node_head, len(parents))
                ci = CommitInfo(graph=ug, hash=h, author=an, email=ae, date_full=ad,
                                subject=subj, parents=parents)
                refs = self.refs_by_hash.get(h, [])
                ci.labels = [r.label or r.name for r in refs]
                ci.local_labels = [r.name for r in refs if r.kind == "local"]
                # current branch first if present (already sorted), otherwise lexicographic first.
                ci.selected_label_index = 0
                idx = len(self.commits)
                self.commits.append(ci)
                self.commit_to_row[idx] = len(self.rows)
                self.rows.append(Row("commit", ug, idx))
                self.graph_width = max(self.graph_width, len(ug))
            else:
                # git emits a separate |\ line immediately after merge commits; keifu folds that
                # into the merge commit line as ─╮, but keeps join lines such as |/.
                if "\\" in line and "/" not in line and "*" not in line:
                    continue
                ug = self._unicode_connector_graph(line)
                if ug.strip():
                    self.rows.append(Row("connector", ug, None))
                    self.graph_width = max(self.graph_width, len(ug))
        self.graph_width = max(1, min(self.graph_width, 20))

    @staticmethod
    def _unicode_connector_graph(prefix: str) -> str:
        s = prefix.rstrip(" ")
        trans = {"|": "│", "\\": "╮", "/": "╯", "-": "─", "*": "●"}
        out = "".join(trans.get(c, c) for c in s)
        # Join lines in git graph are usually |/; keifu renders them as ├─╯.
        out = out.replace("│╯", "├─╯")
        out = out.replace("│ ╯", "├─╯")
        return out.rstrip()

    @staticmethod
    def _unicode_commit_graph(prefix: str, is_head: bool, parent_count: int) -> str:
        s = prefix.rstrip(" ")
        if not s:
            return "◉" if is_head else "●"
        chars = list(s)
        node = "◉" if is_head else "●"
        star_i = None
        for i, c in enumerate(chars):
            if c == "*":
                star_i = i
                chars[i] = node
                break
        trans = {"|": "│", "\\": "╮", "/": "╯", "-": "─"}
        for i, c in enumerate(chars):
            if i == star_i:
                continue
            chars[i] = trans.get(c, c)
        if star_i is not None and parent_count > 1:
            if star_i + 1 < len(chars):
                chars[star_i + 1] = "─"
            if star_i + 2 < len(chars):
                chars[star_i + 2] = "╮"
        return "".join(chars).rstrip()

    def selected_label(self, idx: int) -> str:
        if idx < 0 or idx >= len(self.commits):
            return ""
        c = self.commits[idx]
        if not c.labels:
            return ""
        i = max(0, min(c.selected_label_index, len(c.labels)-1))
        return c.labels[i]

    def selected_local_branch(self, idx: int) -> str:
        label = self.selected_label(idx)
        # Find local branch matching either raw name or combined label.
        h = self.commits[idx].hash if 0 <= idx < len(self.commits) else ""
        for r in self.refs_by_hash.get(h, []):
            if r.kind == "local" and (r.name == label or r.label == label):
                return r.name
        return ""

    def cycle_label(self, idx: int, delta: int):
        if idx < 0 or idx >= len(self.commits):
            return
        c = self.commits[idx]
        if c.labels:
            c.selected_label_index = (c.selected_label_index + delta) % len(c.labels)


class KeifuTUI:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        self.model = GitModel()
        self.selected = 0
        self.scroll = 0
        self.mode = "normal"
        self.input_text = ""
        self.search_index = 0
        self.search_results: List[Tuple[str, str, str]] = []
        self.status_msg = ""
        self.status_kind = ""
        self.last_refresh = 0.0

    def run(self):
        curses.curs_set(0)
        self.stdscr.keypad(True)
        self.stdscr.timeout(250)
        try:
            curses.use_default_colors()
        except Exception:
            pass
        self._init_colors()
        if not self.model.discover():
            return 1
        self.model.refresh()
        self._clamp_selection()
        while True:
            self.draw()
            ch = self.stdscr.get_wch()
            if ch == curses.ERR:
                now = time.time()
                # Lightweight auto-refresh, less aggressive than the original but behaviorally visible.
                if now - self.last_refresh > 10:
                    self._refresh_keep_selection()
                    self.last_refresh = now
                continue
            if self.handle_key(ch):
                return 0

    def _init_colors(self):
        if not curses.has_colors():
            return
        curses.start_color()
        pairs = [
            (1, curses.COLOR_WHITE, -1), (2, curses.COLOR_BLACK, curses.COLOR_CYAN),
            (3, curses.COLOR_YELLOW, -1), (4, curses.COLOR_BLUE, -1),
            (5, curses.COLOR_GREEN, -1), (6, curses.COLOR_RED, -1),
            (7, curses.COLOR_BLACK, curses.COLOR_MAGENTA), (8, curses.COLOR_BLACK, curses.COLOR_GREEN),
            (9, curses.COLOR_BLACK, curses.COLOR_WHITE), (10, curses.COLOR_CYAN, -1),
        ]
        for n, fg, bg in pairs:
            try:
                curses.init_pair(n, fg, bg)
            except Exception:
                pass

    def color(self, n, attr=0):
        try:
            return curses.color_pair(n) | attr
        except Exception:
            return attr

    def handle_key(self, ch):
        if self.mode == "input_branch":
            return self._handle_text_input(ch, branch=True)
        if self.mode == "search":
            return self._handle_search(ch)
        if self.mode == "confirm_delete":
            if ch in ('y', 'Y'):
                self._delete_selected_branch()
                self.mode = "normal"
                self.status_msg = ""
                self._refresh_keep_selection()
            elif ch in ('n', 'N') or self._is_escape(ch):
                self.mode = "normal"
            return False
        if self.mode == "help":
            if ch in ('q', 'Q') or self._is_escape(ch) or ch == '?':
                self.mode = "normal"
            return False
        # normal mode
        if ch in ('q', 'Q') or self._is_escape(ch):
            return True
        if ch in ('j',) or ch == curses.KEY_DOWN:
            self.move_selection(1)
        elif ch in ('k',) or ch == curses.KEY_UP:
            self.move_selection(-1)
        elif ch == 'g' or ch == curses.KEY_HOME:
            self.selected = 0; self.ensure_visible()
        elif ch == 'G' or ch == curses.KEY_END:
            self.selected = max(0, len(self.model.commits)-1); self.ensure_visible()
        elif ch == '\x04':
            self.move_selection(max(1, self.commit_area_height() // 2))
        elif ch == '\x15':
            self.move_selection(-max(1, self.commit_area_height() // 2))
        elif ch in (']', '\t'):
            self.model.cycle_label(self.selected, 1)
        elif ch == '[':
            self.model.cycle_label(self.selected, -1)
        elif ch in ('h',) or ch == curses.KEY_LEFT:
            self.model.cycle_label(self.selected, -1)
        elif ch in ('l',) or ch == curses.KEY_RIGHT:
            self.model.cycle_label(self.selected, 1)
        elif ch == '@':
            self.jump_to_hash(self.model.current_branch_hash or self.model.head_hash)
        elif ch == '\n' or ch == '\r' or ch == curses.KEY_ENTER:
            self.checkout_selected()
        elif ch == 'b':
            if self.model.commits:
                self.mode = "input_branch"; self.input_text = ""
        elif ch == 'd':
            br = self.model.selected_local_branch(self.selected) if self.model.commits else ""
            if br and br != self.model.current_branch:
                self.mode = "confirm_delete"
        elif ch in ('f', 'F'):
            self.fetch_origin()
        elif ch == 'R':
            self._refresh_keep_selection()
        elif ch == '/':
            self.mode = "search"; self.input_text = ""; self.search_index = 0; self.update_search()
        elif ch == '?':
            self.mode = "help"
        return False

    def _is_escape(self, ch):
        return ch == '\x1b' or ch == 27

    def _handle_text_input(self, ch, branch=False):
        if self._is_escape(ch):
            self.mode = "normal"; return False
        if ch == '\n' or ch == '\r' or ch == curses.KEY_ENTER:
            name = self.input_text.strip()
            if branch and name and self.model.commits:
                p = run_git(["branch", name, self.model.commits[self.selected].hash])
                if p.returncode != 0:
                    self.status_msg = "create branch failed: " + first_line(p.stderr or p.stdout)
                    self.status_kind = "ERROR"
                self._refresh_keep_selection()
            self.mode = "normal"; self.input_text = ""; return False
        if ch in (curses.KEY_BACKSPACE, '\b', '\x7f'):
            self.input_text = self.input_text[:-1]
        elif isinstance(ch, str) and ch.isprintable():
            self.input_text += ch
        return False

    def _handle_search(self, ch):
        if self._is_escape(ch):
            self.mode = "normal"; return False
        if ch == '\n' or ch == '\r' or ch == curses.KEY_ENTER:
            if self.search_results:
                self.jump_to_hash(self.search_results[self.search_index][1])
            self.mode = "normal"; return False
        if ch in (curses.KEY_UP, '\x0b'):
            if self.search_results:
                self.search_index = (self.search_index - 1) % len(self.search_results)
                self.jump_to_hash(self.search_results[self.search_index][1], keep_mode=True)
        elif ch in (curses.KEY_DOWN, '\x0a'):
            if self.search_results:
                self.search_index = (self.search_index + 1) % len(self.search_results)
                self.jump_to_hash(self.search_results[self.search_index][1], keep_mode=True)
        elif ch in (curses.KEY_BACKSPACE, '\b', '\x7f'):
            self.input_text = self.input_text[:-1]
            self.update_search()
        elif isinstance(ch, str) and ch.isprintable():
            self.input_text += ch
            self.update_search()
        return False

    def update_search(self):
        q = self.input_text.lower()
        if q:
            self.search_results = [b for b in self.model.all_branch_names if q in b[0].lower()]
        else:
            self.search_results = []
        self.search_index = min(self.search_index, max(0, len(self.search_results)-1))
        if self.search_results:
            self.jump_to_hash(self.search_results[self.search_index][1], keep_mode=True)

    def _delete_selected_branch(self):
        br = self.model.selected_local_branch(self.selected)
        if not br or br == self.model.current_branch:
            return
        p = run_git(["branch", "-d", br])
        if p.returncode != 0:
            self.status_msg = "delete branch failed: " + first_line(p.stderr or p.stdout)
            self.status_kind = "ERROR"

    def checkout_selected(self):
        if not self.model.commits:
            return
        br = self.model.selected_local_branch(self.selected)
        target = br if br else self.model.commits[self.selected].hash
        p = run_git(["checkout", target])
        if p.returncode != 0:
            self.status_msg = "checkout failed: " + first_line(p.stderr or p.stdout)
            self.status_kind = "ERROR"
        self._refresh_keep_selection()

    def fetch_origin(self):
        p = run_git(["fetch", "origin"])
        if p.returncode != 0:
            self.status_msg = "git fetch failed: " + first_line(p.stderr or p.stdout)
            self.status_kind = "ERROR"
        else:
            self.status_msg = "fetch completed"
            self.status_kind = "INFO"
        self._refresh_keep_selection()

    def _refresh_keep_selection(self):
        old_hash = self.model.commits[self.selected].hash if self.model.commits and self.selected < len(self.model.commits) else ""
        self.model.refresh()
        if old_hash:
            self.jump_to_hash(old_hash, keep_mode=True)
        self._clamp_selection()

    def jump_to_hash(self, h, keep_mode=False):
        if not h:
            return
        for i, c in enumerate(self.model.commits):
            if c.hash == h:
                self.selected = i
                self.ensure_visible()
                return

    def _clamp_selection(self):
        if not self.model.commits:
            self.selected = 0
        else:
            self.selected = max(0, min(self.selected, len(self.model.commits)-1))
        self.ensure_visible()

    def move_selection(self, delta):
        if not self.model.commits:
            return
        self.selected = max(0, min(len(self.model.commits)-1, self.selected + delta))
        self.ensure_visible()

    def commit_area_height(self):
        h, w = self.stdscr.getmaxyx()
        return max(3, int(h * 2 / 3) - 2)

    def layout(self):
        h, w = self.stdscr.getmaxyx()
        status_h = 1
        main_h = max(5, h - status_h)
        commit_h = max(3, int(h * 2 / 3))
        if commit_h > main_h - 3:
            commit_h = max(3, main_h - 3)
        detail_h = max(3, main_h - commit_h)
        return h, w, commit_h, detail_h

    def ensure_visible(self):
        if not self.model.rows or not self.model.commits:
            self.scroll = 0; return
        row = self.model.commit_to_row.get(self.selected, 0)
        avail = self.commit_area_height()
        if row < self.scroll:
            self.scroll = row
        elif row >= self.scroll + avail:
            self.scroll = row - avail + 1
        self.scroll = max(0, min(self.scroll, max(0, len(self.model.rows)-avail)))

    def safe_add(self, y, x, s, attr=0):
        h, w = self.stdscr.getmaxyx()
        if y < 0 or y >= h or x >= w:
            return
        if x < 0:
            s = s[-x:]; x = 0
        if not s:
            return
        # Curses may raise on the bottom-right cell; clip conservatively.
        maxlen = max(0, w - x)
        if len(s) > maxlen:
            s = s[:maxlen]
        try:
            self.stdscr.addstr(y, x, s, attr)
        except curses.error:
            pass

    def draw(self):
        self.stdscr.erase()
        h, w, commit_h, detail_h = self.layout()
        if w < 20 or h < 8:
            self.safe_add(0, 0, "Terminal too small")
            self.stdscr.refresh(); return
        self.draw_box(0, 0, commit_h, w, "Commits")
        self.draw_commits(1, 1, commit_h - 2, w - 2)
        detail_y = commit_h
        left_w = w // 2
        right_w = w - left_w
        self.draw_box(detail_y, 0, detail_h, left_w, "Commit Detail")
        self.draw_box(detail_y, left_w, detail_h, right_w, "Changed Files")
        self.draw_detail(detail_y + 1, 1, detail_h - 2, left_w - 2)
        self.draw_files(detail_y + 1, left_w + 1, detail_h - 2, right_w - 2)
        if self.mode == "help":
            self.draw_help_overlay()
        elif self.mode == "input_branch":
            self.draw_input_overlay("New Branch Name")
        elif self.mode == "search":
            self.draw_search_overlay()
        elif self.mode == "confirm_delete":
            br = self.model.selected_local_branch(self.selected)
            self.draw_confirm_overlay(f"Delete branch '{br}'?")
        self.draw_status(h - 1, w)
        self.stdscr.refresh()

    def draw_box(self, y, x, h, w, title):
        if h <= 0 or w <= 1:
            return
        title_s = f" {title} " if title else ""
        if title_s and len(title_s) < w - 2:
            top = "┌" + title_s + "─" * (w - 2 - len(title_s)) + "┐"
        else:
            top = "┌" + "─" * (w - 2) + "┐"
        bot = "└" + "─" * (w - 2) + "┘"
        self.safe_add(y, x, top, self.color(1))
        for yy in range(y + 1, y + h - 1):
            self.safe_add(yy, x, "│" + " " * (w - 2) + "│", self.color(1))
        if h > 1:
            self.safe_add(y + h - 1, x, bot, self.color(1))

    def draw_commits(self, y, x, height, width):
        if not self.model.rows:
            return
        rows = self.model.rows[self.scroll:self.scroll + height]
        right_w = 10 + 2 + 8 + 2 + 7
        for line_no, row in enumerate(rows):
            yy = y + line_no
            if row.kind == "connector":
                graph = row.graph.ljust(self.model.graph_width)
                self.safe_add(yy, x, " " + graph[:self.model.graph_width], self.color(1))
                continue
            ci = self.model.commits[row.commit_index]
            graph = ci.graph.ljust(self.model.graph_width)
            label = ""
            if ci.labels:
                lab = self.model.selected_label(row.commit_index)
                more = len(ci.labels) - 1
                label = f"[{lab}]" + (f" +{more}" if more > 0 else "") + " "
            left_prefix = " " + graph[:self.model.graph_width] + "  " + label
            date = ci.date_full[:10]
            author = (ci.author[:8]).ljust(8)
            short = ci.hash[:7]
            avail_subject = max(0, width - len(left_prefix) - right_w - 1)
            subj = ci.subject
            if len(subj) > avail_subject:
                subj = subj[:avail_subject]
            left = (left_prefix + subj).ljust(max(0, width - right_w))
            line = f"{left}{date}  {author}  {short}"
            attr = self.color(9) if row.commit_index == self.selected else self.color(1)
            self.safe_add(yy, x, line[:width].ljust(width), attr)
        self.draw_branch_popup(y, x, height, width)

    def draw_branch_popup(self, y, x, height, width):
        if not self.model.commits:
            return
        c = self.model.commits[self.selected]
        if len(c.labels) <= 1:
            return
        labels = c.labels
        box_w = min(max(len(s) for s in labels) + 5, max(10, width // 3))
        box_h = min(len(labels) + 2, height)
        bx = x + width - box_w - 1
        by = y + 1
        if by + box_h > y + height:
            by = y + height - box_h
        self.draw_box(by, bx, box_h, box_w, "Branches")
        for i, lab in enumerate(labels[:box_h-2]):
            pointer = "▶" if i == c.selected_label_index else " "
            self.safe_add(by + 1 + i, bx + 1, (pointer + " " + lab).ljust(box_w - 2)[:box_w-2], self.color(1))

    def selected_commit(self) -> Optional[CommitInfo]:
        if self.model.commits and 0 <= self.selected < len(self.model.commits):
            return self.model.commits[self.selected]
        return None

    def draw_detail(self, y, x, height, width):
        c = self.selected_commit()
        if not c:
            self.safe_add(y, x, "Select a commit"[:width].ljust(width), self.color(1))
            return
        lines = [f"Commit: {c.hash}", f"Author: {c.author} <{c.email}>", f"Date:   {c.date_full}"]
        if c.parents:
            lines.append("Parent: " + ", ".join(p[:7] for p in c.parents))
        lines.append("")
        msg = git_out(["show", "-s", "--format=%B", c.hash])
        if not msg:
            msg = c.subject
        for para_line in msg.splitlines():
            if para_line == "":
                lines.append("")
            else:
                lines.extend(textwrap.wrap(para_line, width=max(1, width)) or [""])
        for i in range(height):
            s = lines[i] if i < len(lines) else ""
            self.safe_add(y + i, x, s[:width].ljust(width), self.color(1))

    def file_stats(self, h: str):
        num = run_git(["diff-tree", "--root", "--first-parent", "--numstat", "-r", "--no-commit-id", h])
        nam = run_git(["diff-tree", "--root", "--first-parent", "--name-status", "-r", "--no-commit-id", h])
        stats = []
        status_by_path = {}
        if nam.returncode == 0:
            for line in nam.stdout.splitlines():
                parts = line.split("\t")
                if len(parts) >= 2:
                    st = parts[0][0]
                    path = parts[-1]
                    status_by_path[path] = st
        adds = dels = 0
        if num.returncode == 0:
            for line in num.stdout.splitlines():
                parts = line.split("\t")
                if len(parts) >= 3:
                    a, d, path = parts[0], parts[1], parts[2]
                    ai = int(a) if a.isdigit() else 0
                    di = int(d) if d.isdigit() else 0
                    adds += ai; dels += di
                    st = status_by_path.get(path, "M")
                    stats.append((st, path, ai, di))
        return stats, adds, dels

    def draw_files(self, y, x, height, width):
        c = self.selected_commit()
        if not c:
            return
        stats, adds, dels = self.file_stats(c.hash)
        lines = [f"{len(stats)} files changed  +{adds} -{dels}", ""]
        for st, path, a, d in stats:
            lines.append(f" {st} {path} +{a} -{d}")
        for i in range(height):
            s = lines[i] if i < len(lines) else ""
            self.safe_add(y + i, x, s[:width].ljust(width), self.color(1))

    def draw_input_overlay(self, title):
        h, w = self.stdscr.getmaxyx()
        bw, bh = min(50, max(30, w - 20)), 7
        by, bx = max(0, (h - bh) // 2), max(0, (w - bw) // 2)
        self.draw_box(by, bx, bh, bw, title)
        text = "  " + self.input_text + "_"
        self.safe_add(by + 2, bx + 1, text[:bw-2].ljust(bw-2), self.color(1))
        self.safe_add(by + 4, bx + 3, "Enter: confirm  Esc: cancel"[:bw-6], self.color(1))

    def draw_search_overlay(self):
        h, w = self.stdscr.getmaxyx()
        bw, bh = min(58, max(36, w - 30)), 5 + min(5, max(0, len(self.search_results)))
        by, bx = max(0, (h - bh) // 2), max(0, (w - bw) // 2)
        self.draw_box(by, bx, bh, bw, "Search branches")
        self.safe_add(by + 1, bx + 3, (self.input_text + "_")[:bw-6].ljust(bw-6), self.color(1))
        if self.search_results:
            self.safe_add(by + 2, bx + 1, "─" * (bw - 2), self.color(1))
            for i, (name, hsh, kind) in enumerate(self.search_results[:bh-4]):
                ptr = "▶" if i == self.search_index else " "
                self.safe_add(by + 3 + i, bx + 1, (ptr + " " + name)[:bw-2].ljust(bw-2), self.color(1))
            self.safe_add(by + bh - 2, bx + 3, "↑↓: select  Enter: jump  Esc: cancel"[:bw-6], self.color(1))
        else:
            self.safe_add(by + 3, bx + 3, "Enter: confirm  Esc: cancel"[:bw-6], self.color(1))

    def draw_confirm_overlay(self, msg):
        h, w = self.stdscr.getmaxyx()
        bw, bh = min(50, max(30, w - 20)), 7
        by, bx = max(0, (h - bh) // 2), max(0, (w - bw) // 2)
        self.draw_box(by, bx, bh, bw, "Confirm")
        self.safe_add(by + 2, bx + 3, msg[:bw-6].ljust(bw-6), self.color(1))
        self.safe_add(by + 4, bx + 3, "y: Yes  n: No"[:bw-6], self.color(1))

    def draw_help_overlay(self):
        h, w = self.stdscr.getmaxyx()
        bw, bh = min(76, max(55, w - 44)), min(28, max(18, h - 10))
        by, bx = max(0, (h - bh) // 2), max(0, (w - bw) // 2)
        self.draw_box(by, bx, bh, bw, "Help")
        lines = [
            "Navigation",
            "  j / ↓      Move down",
            "  k / ↑      Move up",
            "  ] / Tab    Select next branch",
            "  [ / S-Tab  Select previous branch",
            "  h / ←      Select left branch (same commit)",
            "  l / →      Select right branch (same commit)",
            "  Ctrl+d     Page down",
            "  Ctrl+u     Page up",
            "  g / Home   Go to top",
            "  G / End    Go to bottom",
            "  @          Jump to HEAD (current branch)",
            "",
            "Git Operations",
            "  Enter      Checkout selected branch/commit",
            "  b          Create new branch",
            "  d          Delete branch",
            "  f          Fetch from origin",
            "",
            "Search",
            "  /          Search branches",
            "  ↑ / C-k    Select previous result",
            "  ↓ / C-j    Select next result",
            "  Enter      Jump to selected branch",
            "  Esc        Cancel search",
        ]
        for i, line in enumerate(lines[:bh-2]):
            self.safe_add(by + 1 + i, bx + 1, line[:bw-2].ljust(bw-2), self.color(1))

    def draw_status(self, y, w):
        branch = self.model.current_branch if self.model.current_branch else ("HEAD" if self.model.head_hash else "")
        if self.mode == "help":
            mid, tag = "Esc/q close help", "HELP"
        elif self.mode in ("input_branch", "search"):
            mid, tag = "Enter confirm  Esc cancel", "INPUT"
        elif self.mode == "confirm_delete":
            mid, tag = "y yes  n no", "CONFIRM"
        elif self.status_msg:
            mid, tag = self.status_msg, self.status_kind or "INFO"
        else:
            mid, tag = "j/k move  Enter checkout  b branch  f fetch  ? help  q quit", ""
        prefix = f" {self.model.repo_name}"
        if branch:
            prefix += f"   {branch}"
        line = prefix + "   " + mid
        if tag:
            if len(line) < w - len(tag) - 1:
                line = line.ljust(w - len(tag) - 1) + " " + tag
        self.safe_add(y, 0, line[:w].ljust(w), self.color(1, curses.A_BOLD))


def first_line(s: str) -> str:
    s = (s or "").strip()
    if not s:
        return "unknown error"
    return s.splitlines()[0]


def main():
    parse_args(sys.argv[1:])
    # The original opens the terminal before doing repository work; without a tty this error appears
    # even inside a Git checkout.
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        sys.stderr.write("Error: No such device or address (os error 6)\n")
        return 1
    # Match the observed repository error in a real terminal.
    p = run_git(["rev-parse", "--show-toplevel"])
    if p.returncode != 0:
        sys.stderr.write("Error: Git repository not found. Please run inside a Git repository.\n\n")
        sys.stderr.write("Caused by:\n")
        sys.stderr.write("    could not find repository at '.'; class=Repository (6); code=NotFound (-3)\n")
        return 1
    locale.setlocale(locale.LC_ALL, "")
    def wrapped(stdscr):
        app = KeifuTUI(stdscr)
        return app.run()
    return curses.wrapper(wrapped) or 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        raise SystemExit(0)
